-- 422: Foundation guard for WASSCE English Language sprint 1 batch 001.
-- Original BrillaPrep practice content; not official WAEC material.
-- Seeds the prod-canonical WASSCE English topic rows for fresh baselines (prod patch 096
-- created five of them; literary_devices exists only on prod). INSERT OR IGNORE no-ops on prod.
-- Also carries the comprehension structured question to keep later migrations under the D1 limit.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS question_content_releases (
    question_id TEXT PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
    batch_id TEXT NOT NULL,
    quality_assurance TEXT NOT NULL CHECK (quality_assurance IN ('automated_beta', 'human_reviewed')),
    release_channel TEXT NOT NULL CHECK (release_channel IN ('beta', 'production')),
    content_label TEXT NOT NULL,
    source_url TEXT NOT NULL,
    official_exam_board_content INTEGER NOT NULL DEFAULT 0 CHECK (official_exam_board_content IN (0, 1)),
    feedback_enabled INTEGER NOT NULL DEFAULT 1 CHECK (feedback_enabled IN (0, 1)),
    released_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
CREATE INDEX IF NOT EXISTS idx_question_content_releases_batch ON question_content_releases(batch_id);
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_comprehension', 'subj_wassce_english', NULL, 'Comprehension', 'wassce-english-comprehension', 'Reading passages, identifying main ideas, inference and vocabulary in context', 'Comprehension questions test close reading: literal recall, inference, and the meaning of words and expressions as used in a passage.', '["Main idea vs supporting detail", "Inference = conclusion from evidence", "Vocabulary in context"]', 1, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_summary', 'subj_wassce_english', NULL, 'Summary Writing', 'wassce-english-summary', 'Identifying topic sentences and condensing passages into concise sentences', 'Summary writing requires identifying the main points of a passage and expressing them briefly in the candidate''s own words, without lifting phrases.', '["Own words, no lifting", "One sentence where required", "Main points only"]', 2, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_essay', 'subj_wassce_english', NULL, 'Essay Writing', 'wassce-english-essay', 'Narrative, descriptive, expository and argumentative essays', 'Essay writing covers the four main WASSCE types: narrative, descriptive, expository and argumentative, each with its own purpose and register.', '["Narrative = story", "Descriptive = senses", "Expository = explain", "Argumentative = persuade"]', 5, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_letter', 'subj_wassce_english', NULL, 'Letter and Report Writing', 'wassce-english-letter', 'Formal and informal letters, reports, articles and speeches', 'Letter and report writing tests format and register: addresses, salutations, headings, subscriptions, and the impersonal structure of official reports.', '["Formal: two addresses + heading", "Yours faithfully pairs with Dear Sir/Madam", "Reports: title, sections, facts"]', 6, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_literary_devices', 'subj_wassce_english', NULL, 'Literary Devices', 'wassce-english-literary-devices', 'Metaphor, simile, personification, hyperbole, alliteration and irony', 'Literary devices are figures of speech and sound patterns writers use for effect; candidates must identify and interpret them in context.', '["Simile uses like/as", "Metaphor states identity", "Personification gives human qualities", "Hyperbole exaggerates"]', 8, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_grammar', 'subj_wassce_english', NULL, 'Grammar and Usage', 'wassce-english-grammar', 'Parts of speech, concord, tenses, active and passive voice', 'Grammar and usage covers concord, tense sequence, voice, and the correction and transformation of sentences.', '["Singular subject takes singular verb", "Past perfect for the earlier of two past actions", "Passive: object becomes subject"]', 4, '2026-08-04T00:00:00.000Z');
CREATE TABLE IF NOT EXISTS _migration_422_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_422_guard;
INSERT INTO _migration_422_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_st_001' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer all the questions. — "Every evening Adjoa sells roasted plantain by the junction. She notes every sale in a small book and sets aside a fifth of her profit for new stock. Customers say her plantain is dearer than her neighbour''s, yet her tray empties first, because she greets every buyer by name and never serves a burnt piece."' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) She sells roasted plantain by the junction. (b) She notes every sale in a small book, and she sets aside a fifth of her profit for new stock. (c) She greets every buyer by name, and she never serves a burnt piece.' AND q.explanation IS 'All answers must come straight from the passage: (a) names the goods and the place; (b) wants the record book and the saved fifth of the profit; (c) wants the personal greeting and the unburnt pieces.' AND q.difficulty IS 'medium' AND q.points IS '10' AND q.marks IS '10' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Read' AND q.assessment_objective IS NULL AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_st_001' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_422_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s1_cmp_st_001_a' AND NOT (sp.id IS 'sqp_q_eng_s1_cmp_st_001_a' AND sp.question_id IS 'q_eng_s1_cmp_st_001' AND sp.part_label IS 'a' AND sp.part_text IS 'What does Adjoa sell, and where does she sell it?' AND sp.marks IS '2' AND sp.correct_answer IS 'She sells roasted plantain by the junction.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '0')) THEN 1 ELSE 0 END;
INSERT INTO _migration_422_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s1_cmp_st_001_b' AND NOT (sp.id IS 'sqp_q_eng_s1_cmp_st_001_b' AND sp.question_id IS 'q_eng_s1_cmp_st_001' AND sp.part_label IS 'b' AND sp.part_text IS 'State two things Adjoa does to manage her money.' AND sp.marks IS '4' AND sp.correct_answer IS 'She notes every sale in a small book, and she sets aside a fifth of her profit for new stock.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_422_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s1_cmp_st_001_c' AND NOT (sp.id IS 'sqp_q_eng_s1_cmp_st_001_c' AND sp.question_id IS 'q_eng_s1_cmp_st_001' AND sp.part_label IS 'c' AND sp.part_text IS 'Give two reasons why Adjoa''s tray empties first although her plantain is dearer.' AND sp.marks IS '4' AND sp.correct_answer IS 'She greets every buyer by name, and she never serves a burnt piece.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '2')) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s1_cmp_st_001', 'topic_wassce_english_comprehension', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Read the passage, then answer all the questions. — "Every evening Adjoa sells roasted plantain by the junction. She notes every sale in a small book and sets aside a fifth of her profit for new stock. Customers say her plantain is dearer than her neighbour''s, yet her tray empties first, because she greets every buyer by name and never serves a burnt piece."', 'structured', NULL, NULL, '(a) She sells roasted plantain by the junction. (b) She notes every sale in a small book, and she sets aside a fifth of her profit for new stock. (c) She greets every buyer by name, and she never serves a burnt piece.', 'All answers must come straight from the passage: (a) names the goods and the place; (b) wants the record book and the saved fifth of the profit; (c) wants the personal greeting and the unburnt pieces.', 'medium', '10', '10', '300', NULL, NULL, '1', NULL, NULL, 'Read', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_eng_s1_cmp_st_001_a', 'q_eng_s1_cmp_st_001', 'a', 'What does Adjoa sell, and where does she sell it?', 2, 'She sells roasted plantain by the junction.', NULL, 'text', 0);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_eng_s1_cmp_st_001_b', 'q_eng_s1_cmp_st_001', 'b', 'State two things Adjoa does to manage her money.', 4, 'She notes every sale in a small book, and she sets aside a fifth of her profit for new stock.', NULL, 'text', 1);
INSERT OR IGNORE INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) VALUES ('sqp_q_eng_s1_cmp_st_001_c', 'q_eng_s1_cmp_st_001', 'c', 'Give two reasons why Adjoa''s tray empties first although her plantain is dearer.', 4, 'She greets every buyer by name, and she never serves a burnt piece.', NULL, 'text', 2);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-english-sprint1-001', 'automated_beta', 'beta', 'Original BrillaPrep WASSCE English practice content; not official WAEC material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_eng_s1_cmp_st_001');
