INSERT INTO _migration_422_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_eng_s1_cmp_st_001')) = 1 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_eng_s1_cmp_st_001') AND r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 1 THEN 1 ELSE 0 END;
DROP TABLE _migration_422_guard;
CREATE TABLE IF NOT EXISTS _migration_422_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_422_guard;
INSERT INTO _migration_422_guard(valid) SELECT CASE WHEN EXISTS (SELECT 1 FROM exam_types WHERE id = 'exam_wassce') AND EXISTS (SELECT 1 FROM subjects WHERE id = 'subj_wassce_english' AND exam_type_id = 'exam_wassce') AND (SELECT COUNT(*) FROM topics t JOIN subjects s ON s.id = t.subject_id WHERE t.id IN ('topic_wassce_english_comprehension', 'topic_wassce_english_summary', 'topic_wassce_english_essay', 'topic_wassce_english_letter', 'topic_wassce_english_literary_devices', 'topic_wassce_english_grammar') AND s.exam_type_id = 'exam_wassce') = 6 THEN 1 ELSE 0 END;
